.game-ui {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 100;
  pointer-events: none;
  color: white;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
}

.game-ui * {
  pointer-events: auto;
}

.game-header {
  position: absolute;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  background: rgba(0,0,0,0.7);
  padding: 10px 20px;
  border-radius: 15px;
  backdrop-filter: blur(5px);
  border: 2px solid rgba(255,255,255,0.2);
}

.game-title {
  font-size: 1.8rem;
  font-weight: bold;
  margin: 0;
  text-shadow: 3px 3px 6px rgba(0,0,0,0.7);
}

.game-status {
  font-size: 1rem;
  margin: 5px 0 0 0;
}

.controls {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 20px;
}

