  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  background: rgba(0,0,0,0.7);
  padding: 15px;
  border-radius: 15px;
  backdrop-filter: blur(5px);
  border: 2px solid rgba(255,255,255,0.2);
  min-width: 180px;
}

.team-name {
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 5px;
}

